#!/usr/bin/env python3
"""
herdr-links — extract URLs from herdr panes, numbered for voice control.

Default: scan all live panes, print numbered URL list, open by number.
--json: structured JSON output with per-pane and aggregated data.
--focused: scan only the focused pane.
--pane ID: scan a single pane.
--workspace ID: scan panes in a workspace.
--min-count N: include only URLs appearing in >= N panes (default 1).
--local: include localhost/127.0.0.1 URLs (excluded by default).
"""

import argparse
import json
import re
import subprocess
import sys
from datetime import datetime, timezone

ANSI_RE = re.compile(r"\x1b\[[0-9;]*[mGKHF]|\x1b\][^\x07]*\x07|\x1b[=>]")
URL_RE = re.compile(
    r"https?://[^\s<>\"')}\]]+|http://localhost:[0-9]+[^\s<>\"')}\]]*"
)
TRAILING_PUNCT = ".,)]"


def run_herdr(args):
    result = subprocess.run(
        ["herdr", *args], capture_output=True, text=True
    )
    return result


def strip_ansi(text):
    return ANSI_RE.sub("", text)


def clean_url(url):
    while url and url[-1] in TRAILING_PUNCT:
        url = url[:-1]
    return url


def extract_urls(text):
    """Return list of (url, context) in order of first appearance, deduped."""
    seen = {}
    order = []
    for line in text.splitlines():
        clean_line = line.strip()
        for match in URL_RE.finditer(line):
            url = clean_url(match.group(0))
            if not url:
                continue
            context = clean_line[:100]
            if url not in seen:
                seen[url] = {"url": url, "context": context, "count": 0}
                order.append(url)
            seen[url]["count"] += 1
    return [seen[u] for u in order]


def pane_label(pane):
    return (
        pane.get("label")
        or pane.get("terminal_title_stripped")
        or pane["pane_id"]
    )


def scan_pane(pane):
    pane_id = pane["pane_id"]
    entry = {
        "pane_id": pane_id,
        "workspace_id": pane.get("workspace_id"),
        "focused": bool(pane.get("focused")),
        "agent_status": pane.get("agent_status"),
        "cwd": pane.get("cwd"),
        "label": pane_label(pane),
        "urls": [],
    }

    result = run_herdr(
        ["pane", "read", pane_id, "--source", "recent", "--format", "text"]
    )
    if result.returncode != 0:
        entry["read_error"] = (
            result.stderr or result.stdout or "unknown error"
        ).strip()
        return entry

    text = strip_ansi(result.stdout)
    entry["urls"] = extract_urls(text)
    return entry


def build_all_urls(panes, min_count, include_local=False):
    agg = {}
    for pane in panes:
        for u in pane["urls"]:
            url = u["url"]
            if not include_local:
                if any(
                    x in url.lower()
                    for x in ["localhost", "127.0.0.1", "macbook"]
                ):
                    continue
            if url not in agg:
                agg[url] = {"url": url, "panes": [], "total_count": 0}
            agg[url]["panes"].append(pane["pane_id"])
            agg[url]["total_count"] += u["count"]

    all_urls = [v for v in agg.values() if v["total_count"] >= min_count]
    all_urls.sort(key=lambda x: x["total_count"], reverse=True)
    return all_urls


def main():
    parser = argparse.ArgumentParser(
        description="Scan Herdr panes for URLs, numbered for voice control"
    )
    parser.add_argument(
        "open",
        nargs="?",
        help="open URL by number (e.g., 'herdr-links open 3')",
    )
    parser.add_argument(
        "--json",
        action="store_true",
        help="output structured JSON instead of numbered list",
    )
    parser.add_argument(
        "--focused", action="store_true", help="scan only the focused pane"
    )
    parser.add_argument("--pane", help="scan a single pane id")
    parser.add_argument("--workspace", help="scan all panes in a workspace")
    parser.add_argument(
        "--min-count",
        type=int,
        default=1,

        default=1,
        help="minimum total count for aggregated URLs (default 1)",
    )
    parser.add_argument(
