/**
 * InteractiveTerminalNudge.hook.ts — when a Bash command fails because it needs
 * an interactive terminal (a TTY), tell the agent to drive a herdr pane instead
 * of handing the command back to the captain.
 *
 * THE BEHAVIOR THIS CLOSES: a command like `claude --cloud` refuses non-TTY
 * stdout; the agent then says "run this yourself" even though herdr can host a
 * real terminal (`herdr pane split` / `run` / `read` / `send-keys`).
 *
 * Fires on PostToolUse AND PostToolUseFailure for Bash (a failing exit code
 * only reaches the latter). NEVER blocks — advisory additionalContext only.
 * Disable: INTERACTIVE_TERMINAL_NUDGE_DISABLED=1.
 */

const TTY_RE =
  /requires an interactive terminal|needs an interactive terminal|must be run (?:from|in) (?:a )?(?:TTY|terminal)|requires a TTY|not a (?:tty|terminal)|stdin is not a (?:tty|terminal)|stdout is not a (?:tty|terminal)|the input device is not a TTY|Raw mode is not supported|run from a TTY/i;

export function needsTty(text: string): boolean {
  return TTY_RE.test(text);
}

export function responseText(input: Record<string, unknown>): string {
  const parts: string[] = [];
  for (const k of ['tool_response', 'error', 'tool_result']) {
    const v = input[k];
    if (typeof v === 'string') parts.push(v);
    else if (v && typeof v === 'object') parts.push(JSON.stringify(v));
  }
  return parts.join('\n');
}

export function buildNudge(): string {
  return [
    'INTERACTIVE TERMINAL NEEDED — do not hand this back to the captain. herdr can host a real TTY:',
    '1. herdr pane split --current --direction down --cwd <dir> --no-focus   (prints the new pane_id)',
    '2. herdr pane run <pane_id> <command>',
    '3. herdr pane read <pane_id>   (or: herdr pane wait-output <pane_id> ...)  to see the result',
    '4. herdr agent send-keys <pane_id> <KEY>...  to answer prompts; herdr pane close <pane_id> when done.',
    'Only escalate if the pane output shows a login/credential/permission step you cannot do.',
  ].join('\n');
}

async function main(): Promise<void> {
  if (process.env.INTERACTIVE_TERMINAL_NUDGE_DISABLED === '1') return;
  let input: Record<string, unknown> = {};
  try {
    const stdin = await Bun.stdin.text();
    if (stdin.trim()) input = JSON.parse(stdin);
  } catch {
    return;
  }
  if (input.tool_name !== 'Bash') return;
  if (input.agent_id) return;
  if (!needsTty(responseText(input))) return;
  const event = typeof input.hook_event_name === 'string' ? input.hook_event_name : 'PostToolUse';
  console.log(
    JSON.stringify({ hookSpecificOutput: { hookEventName: event, additionalContext: buildNudge() } }),
  );
}

