 *   2. Double-backtick inline code spans (`` … ``)
 *   3. Single-backtick inline code spans (` … `)
 *   4. Double-quoted strings (" … ")
 */
export function stripQuotedSpans(text: string): string {
  return text
    .replace(/```[\s\S]*?```/g, m => ' '.repeat(m.length))
    .replace(/``[^`]{1,300}``/g, m => ' '.repeat(m.length))
    .replace(/`[^`]{1,300}`/g, m => ' '.repeat(m.length))
    .replace(/"[^"]{1,300}"/g, m => ' '.repeat(m.length));
}

/**
 * Centralized pattern matcher. Calls stripQuotedSpans ONCE on the input text,
 * runs every pattern against the stripped version, then extracts snippets
 * from the ORIGINAL text using the match indices (which are valid because
 * stripQuotedSpans preserves positions).
 */
export function matchPatterns(
  text: string,
  patterns: Array<{ label: string; rx: RegExp }>,
): Match[] {
  const stripped = stripQuotedSpans(text);
  return patterns.flatMap(({ label, rx }) => {
    const m = stripped.match(rx);
    if (!m) return [];
    const idx = m.index ?? 0;
    const snippet = text
      .slice(Math.max(0, idx - 30), Math.min(text.length, idx + m[0].length + 30))
      .replace(/\s+/g, ' ')
      .trim();
    return [{ label, snippet }];
  });
}

