];

/** The `! <cmd>` paste-in form usually sits inside a code span/block, which matchPatterns strips. */
const BANG_CMD = /(?:^|\n|`)[ \t]*!\s+\S/;

export const GENERIC_HANDBACK_NUDGE =
  'Do not hand this back. A command that needs a TTY can run in a real terminal session you drive yourself ' +
  '(a terminal multiplexer or pane). Open one, run the command there, read its output, and report the result.';

export function behaviorPath(env: Record<string, string | undefined> = process.env): string {
