    join(env.HOME ?? homedir(), '.config', 'hook-behaviors', 'interactive-terminal.md');
}

export function loadBehavior(path: string = behaviorPath()): string {
  try {
    const t = readFileSync(path, 'utf-8').trim();
    if (t) return t;
  } catch {
    /* none installed → generic */
  }
  return GENERIC_HANDBACK_NUDGE;
}

