/**
 * lib/transcript-parser.ts — minimal replacement for the removed ../PAI/TOOLS/TranscriptParser
 * (robots-4oza5). Reads a Claude Code JSONL transcript and returns the last assistant text.
 */
import { existsSync, readFileSync } from 'node:fs';

export interface ParsedTranscript {
  raw: string;
  lastMessage: string;
  currentResponseText: string;
  voiceCompletion: string;
  plainCompletion: string;
  structured: Record<string, unknown>;
  responseState: string;
}

function textOf(content: unknown): string {
  if (typeof content === 'string') return content;
  if (Array.isArray(content)) {
    return content
      .filter((b) => b && typeof b === 'object' && (b as { type?: string }).type === 'text')
      .map((b) => String((b as { text?: unknown }).text ?? ''))
      .join('\n');
  }
  return '';
}

export function parseTranscript(path: string): ParsedTranscript {
  const empty: ParsedTranscript = { raw: '', lastMessage: '', currentResponseText: '', voiceCompletion: '', plainCompletion: '', structured: {}, responseState: 'completed' };
  if (!path || !existsSync(path)) return empty;
  const raw = readFileSync(path, 'utf-8');
  let last = '';
  for (const line of raw.split('\n')) {
    if (!line.trim()) continue;
    try {
      const e = JSON.parse(line);
      const msg = e.message ?? e;
      if ((e.type === 'assistant' || msg.role === 'assistant')) {
        const t = textOf(msg.content).trim();
        if (t) last = t;
      }
    } catch {
      /* skip malformed line */
    }
  }
  return { ...empty, raw, lastMessage: last, currentResponseText: last, plainCompletion: last };
}
