import type { BehaviorModule, Match } from './types';

const PR_URL = /https:\/\/github\.com\/([\w.-]+)\/([\w.-]+)\/pull\/(\d+)/g;
const ASKS_MERGE = /\b(say go|want me to merge|shall i merge|awaiting your (?:merge|word|go)|your (?:word|go|okay|ok) to merge|merge (?:call|approval)|ready for your merge|need(?:s)? your (?:merge|go))\b/i;

export const GENERIC_STANCE_NUDGE =
