/**
 * BehaviorEnforcement/pr-stance.ts — check-PR-stance module.
 *
 * Catches asking the captain for merge permission on a PR in a project whose
 * registered posture already has merge authority (yolo). Stance is read live from
 * the firstmate project registry (bin/fm-project-mode.sh), never assumed.
 *
 * Environment-specific wording is swapped in from ~/.config/hook-behaviors/pr-stance.md
 * (override: HOOK_BEHAVIOR_PR_STANCE).
 */

import { readFileSync } from 'node:fs';
import { homedir } from 'node:os';
import { join } from 'node:path';
import { spawnSync } from 'node:child_process';
import type { BehaviorModule, Match } from './types';

const PR_URL = /https:\/\/github\.com\/([\w.-]+)\/([\w.-]+)\/pull\/(\d+)/g;
const ASKS_MERGE = /\b(say go|want me to merge|shall i merge|awaiting your (?:merge|word|go)|your (?:word|go|okay|ok) to merge|merge (?:call|approval)|ready for your merge|need(?:s)? your (?:merge|go))\b/i;

export const GENERIC_STANCE_NUDGE =
  'Check the project merge stance before asking. If the registry shows yolo for this project, merge the green, in-scope PR yourself ' +
  '(guarded merge script when a task record exists, otherwise gh pr merge --squash) and report the outcome. Ask only for red/missing checks or destructive/irreversible/security-sensitive changes.';

export function behaviorPath(env: Record<string, string | undefined> = process.env): string {
  return env.HOOK_BEHAVIOR_PR_STANCE ?? join(env.HOME ?? homedir(), '.config', 'hook-behaviors', 'pr-stance.md');
}

export function loadBehavior(path: string = behaviorPath()): string {
  try {
    const t = readFileSync(path, 'utf-8').trim();
    if (t) return t;
  } catch { /* none installed → generic */ }
  return GENERIC_STANCE_NUDGE;
}

/** "direct-PR on" → yolo on. */
export function projectIsYolo(repo: string, env: Record<string, string | undefined> = process.env): boolean {
  const bin = env.FM_PROJECT_MODE_BIN ?? join(env.HOME ?? homedir(), 'fm_home', 'firstmate', 'bin', 'fm-project-mode.sh');
  const r = spawnSync(bin, [repo], { encoding: 'utf-8', timeout: 5000 });
  return r.status === 0 && /\bon\s*$/.test((r.stdout ?? '').trim());
}

export function checkStance(text: string, isYolo: (repo: string) => boolean = projectIsYolo): Match[] {
  if (!ASKS_MERGE.test(text)) return [];
  const out: Match[] = [];
  for (const m of text.matchAll(PR_URL)) {
    if (isYolo(m[2])) out.push({ label: 'yolo-project-ask', snippet: `${m[2]}#${m[3]} asked for merge permission` });
  }
  return out;
}

export const prStanceModule: BehaviorModule = {
  name: 'pr-stance',
  gate: 'always',
  check: (text) => checkStance(text),
  nudge(matches) {
    return [
      `🔴 pr-stance: asked for merge permission on a yolo project  [${[...new Set(matches.map((m) => m.label))].join(', ')}]`,
      `snippet: "${matches[0]?.snippet ?? ''}"`,
      loadBehavior(),
    ].join('\n');
  },
};
EOF
