import { test, expect } from 'bun:test';
import { checkStance, loadBehavior, GENERIC_STANCE_NUDGE } from '../events/stop/BehaviorEnforcement/pr-stance';

const url = 'https://github.com/trillium/displayd/pull/70';
test('flags asking merge permission on a yolo project', () => {
  expect(checkStance(`PR ready ${url}. Say go and I'll merge.`, () => true).length).toBe(1);
});
test('leaves non-yolo projects and plain reports alone', () => {
  expect(checkStance(`PR ready ${url}. Say go and I'll merge.`, () => false)).toEqual([]);
  expect(checkStance(`Merged ${url}.`, () => true)).toEqual([]);
});
test('behavior file absent → generic', () => {
  expect(loadBehavior('/nonexistent/x.md')).toBe(GENERIC_STANCE_NUDGE);
});
EOF
