import SwiftUI
import UIKit

/// Principal class of the Share Extension (NSExtensionPrincipalClass in project.yml).
/// Picking "Firstmate" in the share sheet loads the items and shows a compose step (optional chips + note, steer-565);
/// Send posts them: URL/text as a foreground JSON POST,
/// images/files as a background multipart upload that outlives the sheet, or a foreground one when the build has
/// no app group (the wildcard-profile OTA build) and nsurlsessiond could not reach a shared container.
final class ShareViewController: UIViewController {
    private let model = ShareStatusModel()
    private var started = false
    private var payload: SharePayload?
    private var settings: ShareSettings?
    private lazy var workDir = FileManager.default.temporaryDirectory
        .appendingPathComponent("share-\(UUID().uuidString)", isDirectory: true)

    override func viewDidLoad() {
        super.viewDidLoad()
        let host = UIHostingController(rootView: ShareStatusView(
            model: model,
            onSend: { [weak self] in self?.start() },
            onRetry: { [weak self] in self?.start() },
            onClose: { [weak self] in self?.close() }
        ))
        addChild(host)
        host.view.frame = view.bounds
        host.view.autoresizingMask = [.flexibleWidth, .flexibleHeight]
        view.addSubview(host.view)
        host.didMove(toParent: self)
    }

    override func viewDidAppear(_ animated: Bool) {
        super.viewDidAppear(animated)
        if !started {
            started = true
            Task { await load() }
        }
    }

    /// Loads the shared items once, then waits on the compose step.
    private func load() async {
        model.state = .loading
        do {
            let settings = try ShareSettings.load(from: KeychainSecretStore(config: SharedConfig()))
            _ = try settings.validatedEndpoint()
            let items = extensionContext?.inputItems.compactMap { $0 as? NSExtensionItem } ?? []
            let payload = await ItemLoader.payload(from: items, source: "iOS share sheet", workDir: workDir)
            guard !payload.isEmpty else { throw ShareError.nothingToShare }
            self.settings = settings
            self.payload = payload
            model.state = .composing(payload.summary)
        } catch {
            model.state = .failed(error.localizedDescription)
        }
    }

    /// Send, or Retry after a failure (reloads when loading itself failed).
    private func start() {
