/// Share-sheet chips: what firstmate should do with a share. The raw values are the receiver's intent keys
/// (`INTENTS` in receiver/fms_receiver.py), which become the bead's `Ask:` line.
enum ShareIntent: String, CaseIterable, Sendable, Identifiable {
    case person
    case task
    case idea
    case later

    var id: String { rawValue }

    var label: String {
        switch self {
        case .person: "Person"
        case .task: "Task"
        case .idea: "Idea"
        case .later: "Later"
        }
    }

    var systemImage: String {
        switch self {
        case .person: "person.crop.circle.badge.plus"
        case .task: "checklist"
        case .idea: "lightbulb"
        case .later: "bookmark"
        }
    }
}

/// The optional follow-on information sent with a share: chips plus a free-text note. Both may be empty.
struct ShareAsk: Equatable, Sendable {
    var intents: [ShareIntent] = []
    var note: String = ""

    var trimmedNote: String { note.trimmingCharacters(in: .whitespacesAndNewlines) }
    var isEmpty: Bool { intents.isEmpty && trimmedNote.isEmpty }

    /// Receiver fields: `intents` comma-separated in the chips' fixed order, `note` trimmed. Empty parts are omitted.
    var fields: [String: String] {
        var out: [String: String] = [:]
        let keys = ShareIntent.allCases.filter(intents.contains).map(\.rawValue)
        if !keys.isEmpty { out["intents"] = keys.joined(separator: ",") }
        if !trimmedNote.isEmpty { out["note"] = trimmedNote }
        return out
    }
}

